import json
def main(action, input_data):
    if "url" in input_data:
        content = {"type": "url_resource", "url": input_data["url"], "content": "模拟获取的资源内容"}
    elif "code" in input_data:
        content = {"type": "code", "language": "java", "lines": len(input_data["code"].splitlines())}
    else:
        content = {"type": "requirement", "text": input_data.get("text", "")}
    return {"resource": content, "action": action}

